// Generated by Cypress Author on 2026-11-18

describe('Admin Home Dashboard - Member / Creator View', () => {
  const mockHomeData = {
    totalRecipes: 8,
    recentRecipes: [
      {
        id: '1',
        title: 'Smoked Salmon Bagel',
        category: 'Breakfast',
        prepTime: '10 mins',
        author: 'Chef Delisha',
      },
      {
        id: '2',
        title: 'Tuscan Garlic Chicken',
        category: 'Dinner',
        prepTime: '25 mins',
        author: 'Chef Delisha',
      },
    ],
  };

  beforeEach(() => {
    // Authenticate as active member
    cy.intercept('GET', '**/auth/me*', {
      statusCode: 200,
      body: {
        user: {
          username: 'delisha',
          email: 'delisha@example.com',
        },
      },
    }).as('getCurrentUser');

    cy.intercept('GET', '**/auth/session*', {
      statusCode: 200,
      body: {
        role: 'member',
        status: 'active',
        tenant: null,
        isImpersonating: false,
      },
    }).as('getMemberSession');
  });

  it('render dashboard with recipe statistics → displays total recipe count and recent creation cards', () => {
    cy.intercept('GET', '**/api/home*', {
      statusCode: 200,
      body: mockHomeData,
    }).as('getHomeData');

    cy.visit('/');
    cy.wait('@getHomeData');

    // Total Recipes stats card
    cy.contains('span', 'Total Recipes').should('be.visible');
    cy.contains('p', '8').should('be.visible');
    cy.contains('p', 'Active dishes in this tenant').should('be.visible');

    // Quick action cards
    cy.contains('span', 'Recipe Directory').should('be.visible');
    cy.contains('a', 'View All Recipes').should('be.visible');
    cy.contains('span', 'Creator Hub').should('be.visible');
    cy.contains('button', '+ Create Recipe').should('be.visible');

    // Recent creations cards
    cy.contains('h2', 'Recent Creations').should('be.visible');
    cy.contains('h3', 'Smoked Salmon Bagel').should('be.visible');
    cy.contains('span', 'Breakfast').should('be.visible');
    cy.contains('p', 'By Chef Delisha').should('be.visible');
    cy.contains('span', '10 mins prep').should('be.visible');

    cy.contains('h3', 'Tuscan Garlic Chicken').should('be.visible');
    cy.contains('span', 'Dinner').should('be.visible');
    cy.contains('span', '25 mins prep').should('be.visible');

    // Edit link on card points to recipe edit route
    cy.get('a[href*="/recipes/edit/1"]').should('be.visible').and('contain', 'Edit');
    cy.get('a[href*="/recipes/edit/2"]').should('be.visible').and('contain', 'Edit');
  });

  it('render dashboard with no recipes → displays zero count and empty state message', () => {
    cy.intercept('GET', '**/api/home*', {
      statusCode: 200,
      body: {
        totalRecipes: 0,
        recentRecipes: [],
      },
    }).as('getHomeEmpty');

    cy.visit('/');
    cy.wait('@getHomeEmpty');

    // Zero count in stats card
    cy.contains('p', '0').should('be.visible');

    // Empty state container and illustration
    cy.contains('p', 'No recipes found yet. Get started by creating your first recipe!').should(
      'be.visible',
    );
  });

  it("click 'View All Recipes' link → navigates to /recipes route", () => {
    cy.intercept('GET', '**/api/home*', {
      statusCode: 200,
      body: mockHomeData,
    }).as('getHomeData');

    cy.intercept('GET', '**/api/recipes*', {
      statusCode: 200,
      body: [],
    }).as('getRecipes');

    cy.visit('/');
    cy.wait('@getHomeData');

    cy.contains('a', 'View All Recipes').click();
    cy.url().should('include', '/recipes');
  });

  it("click '+ Create Recipe' button → opens create recipe dialog", () => {
    cy.intercept('GET', '**/api/home*', {
      statusCode: 200,
      body: mockHomeData,
    }).as('getHomeData');

    cy.visit('/');
    cy.wait('@getHomeData');

    cy.contains('button', '+ Create Recipe').click();

    cy.get('mat-dialog-container').should('be.visible');
    cy.get('mat-dialog-container').contains('Create New Recipe').should('be.visible');
    cy.get('input#title').should('be.visible');
  });

  it('toggle mobile navigation menu on small screen → opens and closes mobile navigation drawer', () => {
    cy.intercept('GET', '**/api/home*', {
      statusCode: 200,
      body: mockHomeData,
    }).as('getHomeData');

    cy.viewport('iphone-x');
    cy.visit('/');
    cy.wait('@getHomeData');

    // Desktop nav is hidden on mobile
    cy.get('nav.hidden.md\\:flex').should('not.be.visible');

    // Mobile hamburger menu toggle button is visible
    cy.get('button[aria-label="Toggle navigation menu"]').should('be.visible').click();

    // Mobile nav drawer is now rendered and visible
    cy.get('nav[aria-label="Mobile Navigation"]').should('be.visible');
    cy.get('nav[aria-label="Mobile Navigation"]').contains('a', 'Dashboard').should('be.visible');
    cy.get('nav[aria-label="Mobile Navigation"]').contains('a', 'Recipes').should('be.visible');
    cy.get('nav[aria-label="Mobile Navigation"]').contains('a', 'Contacts').should('be.visible');
    cy.get('nav[aria-label="Mobile Navigation"]').contains('a', 'Other Pages').should('be.visible');

    // Toggle menu closed
    cy.get('button[aria-label="Toggle navigation menu"]').click();
    cy.get('nav[aria-label="Mobile Navigation"]').should('not.exist');
  });
});

describe('Admin Home Dashboard - Administrator Control Center View', () => {
  beforeEach(() => {
    cy.intercept('GET', '**/auth/me*', {
      statusCode: 200,
      body: {
        user: {
          username: 'superadmin',
          email: 'admin@platform.com',
        },
      },
    }).as('getCurrentUser');

    cy.intercept('GET', '**/auth/session*', {
      statusCode: 200,
      body: {
        role: 'admin',
        status: 'active',
        tenant: null,
        isImpersonating: false,
      },
    }).as('getAdminSession');
  });

  it('signed in as platform administrator without impersonation → displays administrator control center and directory links', () => {
    cy.visit('/');
    cy.wait('@getAdminSession');

    // Header & description
    cy.contains('h1', 'Administrator Control Center').should('be.visible');
    cy.contains('p', 'You are signed in as a Platform Administrator.').should('be.visible');

    // Link to users / tenant directory
    cy.contains('a', 'Open Users & Tenant Directory')
      .should('be.visible')
      .and('have.attr', 'href', '/users');

    // Feature explanation cards
    cy.contains('h3', 'Sandboxed Member Content').should('be.visible');
    cy.contains('span', 'Tenant Isolation').should('be.visible');
    cy.contains('h3', 'Registration Gate').should('be.visible');
    cy.contains('span', 'Waiting Room').should('be.visible');
  });
});

describe('Admin Home Dashboard - Unauthenticated Guard', () => {
  it('unauthenticated user visits / → redirects to login page with returnUrl', () => {
    cy.intercept('GET', '**/auth/me*', {
      statusCode: 401,
      body: { error: 'Unauthorized' },
    }).as('getUnauthorizedUser');

    cy.visit('/');

    cy.url().should('include', '/login');
    cy.get('#login-email').should('be.visible');
  });
});
